class Submission(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    city: Annotated[str, Field(pattern="^[a-z0-9]+(?:-[a-z0-9]+)*$")]
    venue: Venue | Venue1
    beer: Annotated[str | None, Field(max_length=80)]
    """
    As written; null for "outra / não sei"
    """
    format_code: Annotated[str, Field(max_length=40)]
    """
    A format from the catalog, e.g. garrafa_600
    """
    price: Annotated[float, Field(gt=0.0, le=10000.0)]
    """
    What was paid, in currency units (9.99)
    """
    units: Annotated[int | None, Field(ge=1, le=50)] = None
    packaging: Literal["single", "balde", "torre", "combo", "dobro"] | None = None
    kind: Literal["regular", "happy_hour", "promo", "combo", "open_bar"] | None = None
    open_bar_minutes: Annotated[int | None, Field(gt=0, le=1440)] = None
    schedules: Annotated[list[ScheduleDraft] | None, Field(max_length=14)] = None
    valid_from: date | None = None
    valid_until: date | None = None
    conditions: Annotated[str | None, Field(max_length=280)] = None
    service_charge_pct: Annotated[int | None, Field(ge=0, le=30)] = None
    couvert: Annotated[float | None, Field(ge=0.0, le=1000.0)] = None
    attributes: Annotated[
        list[Literal["musica_ao_vivo", "transmite_jogos", "area_externa", "pe_na_areia"]] | None,
        Field(max_length=4),
    ] = None
    seen_in: Literal["menu", "poster", "instagram", "staff", "receipt", "other"] | None = None
    link: AnyUrl | None = None
    observed_on: date | None = None
    """
    City-local date the price was seen
    """
    notes: Annotated[str | None, Field(max_length=500)] = None
    is_owner: bool | None = None
    """
    Sent by the bar's owner or manager
    """
    nickname: Annotated[str | None, Field(max_length=40, min_length=2)] = None
    """
    Credited on the site when the price goes live
    """
    email: Annotated[str | None, Field(max_length=200)] = None
    """
    Only to say "seu preço está no ar"; deleted after
    """
    consent: bool | None = None
    """
    LGPD consent: required with an email
    """
    turnstile: Annotated[str, Field(max_length=2048, min_length=1)]
    """
    Cloudflare Turnstile token
    """


